@armProviderNamespace @service namespace Microsoft.Example;
model WidgetProperties { displayName: string; description?: string; }
model Widget is TrackedResource<WidgetProperties> { ...ResourceNameParameter<Widget>; }
model UnsafeWidgetPatch {
  location?: string;
  properties: {
    displayName: string;
    extra?: string;
    description?: string = "default";
  };
}

@armResourceOperations
interface Widgets {
  update is ArmCustomPatchSync<Widget, UnsafeWidgetPatch>;
}

